export const DEFAULT_PROJECT='robot-1';
export function normalizeProjects(w){
 const projects=w.projects?.length?w.projects:[{id:DEFAULT_PROJECT,name:'Robot 1',archived:false},{id:'robot-2',name:'Robot 2',archived:false},{id:'robot-cart',name:'Robot Cart',archived:false}];
 const fallback=projects.find(p=>!p.archived)?.id||projects[0].id;
 const students=w.students??[...new Set((w.parts||[]).filter(p=>!/^demo-part-/.test(p.id)&&p.number?.startsWith('7028')).flatMap(p=>[p.owner,p.assignedTo]).filter(n=>typeof n==='string'&&n.trim()).map(n=>n.trim()))].sort().map((name,n)=>({id:'student-'+n,name,active:true}));
 return {...w,students,projects,onshapeProjectId:w.onshapeProjectId===undefined?fallback:w.onshapeProjectId,...Object.fromEntries(['parts','cots','materials'].map(k=>[k,(w[k]||[]).map(r=>({...r,projectId:r.projectId||fallback}))]))};
}
export function validProjects(w){if(w.students!==undefined&&(!Array.isArray(w.students)||w.students.length>500||new Set(w.students.map(s=>s?.id)).size!==w.students.length||new Set(w.students.map(s=>s?.name?.trim().toLowerCase())).size!==w.students.length||!w.students.every(s=>s&&typeof s.id==='string'&&s.id&&typeof s.name==='string'&&s.name.trim()&&s.name.length<=100&&typeof s.active==='boolean')))return false;if(w.projects===undefined)return true;return Array.isArray(w.projects)&&w.projects.length>0&&w.projects.length<=100&&new Set(w.projects.map(p=>p?.id)).size===w.projects.length&&new Set(w.projects.map(p=>p?.name?.trim().toLowerCase())).size===w.projects.length&&w.projects.some(p=>p&&!p.archived)&&w.projects.every(p=>p&&typeof p.id==='string'&&p.id.length>0&&p.id.length<=100&&typeof p.name==='string'&&p.name.trim()&&p.name.length<=100&&typeof p.archived==='boolean')&&['parts','materials','cots'].every(k=>(w[k]||[]).every(r=>r&&(r.projectId===undefined||typeof r.projectId==='string'&&w.projects.some(p=>p.id===r.projectId))))&&(!w.onshapeProjectId||w.projects.some(p=>p.id===w.onshapeProjectId&&!p.archived));}
export const projectScope=(w,id)=>({...w,...Object.fromEntries(['parts','materials','cots'].map(k=>[k,(w[k]||[]).filter(r=>r.projectId===id)]))});
export function mergeProject(w,scope,id){if(!w.projects.some(p=>p.id===id&&!p.archived))throw Error('Choose an active project.');return {...w,...Object.fromEntries(['parts','materials','cots'].map(k=>[k,[...(w[k]||[]).filter(r=>r.projectId!==id),...(scope[k]||[]).map(r=>({...r,projectId:id}))]]))};}
export function reviewFingerprint(p){return JSON.stringify([p.projectId,p.id,p.name,p.number,p.quantity,p.completedQty??(p.status==='Finished'?p.quantity:0),p.status,p.material,p.process,p.cad,p.readiness,p.blocked]);}
export function approvalStatus(p){return p.status==='Finished'?(p.approval?.status||'pending'):'not-submitted';}
export function preserveApprovals(previous,next){const old=new Map(previous.parts.map(p=>[p.id,p]));return {...next,reviewLog:previous.reviewLog||[],parts:next.parts.map(p=>{const before=old.get(p.id),copy={...p};delete copy.approval;if(p.status==='Finished')copy.approval=before&&reviewFingerprint(before)===reviewFingerprint(p)&&before.approval?before.approval:{status:'pending',submittedAt:new Date().toISOString()};return copy;})};}
